"""Vellum House visual layer. Persian is the canonical homepage."""
import re,json,html
from pathlib import Path

def build_visual(R):
 C=json.loads((R/'content.json').read_text())
 def esc(s):return html.escape(str(s),quote=True)
 def page(p,l):return ('index' if l=='fa' else 'en')+'.html' if p=='home' else p+('-fa' if l=='fa' else '')+'.html'
 def icon(n):
  paths={'arrow':'M6 18 18 6M6 6h12v12','book':'M12 6c-3-2-6-2-9-1v14c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1Zm0 0v14','target':'M12 3a9 9 0 1 0 9 9M12 7a5 5 0 1 0 5 5M12 12l9-9M16 3h5v5','chart':'M4 3v17h17M7 15l4-5 4 2 6-7','cap':'m2 9 10-5 10 5-10 5L2 9Zm4 3v6c4 3 8 3 12 0v-6M22 9v8','message':'M21 15a3 3 0 0 1-3 3H9l-6 3V6a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3v9ZM7 8h10M7 12h7','check':'m5 12 4 4L19 6','calendar':'M4 5h16v16H4V5ZM8 2v6M16 2v6M4 10h16M8 14h3M8 17h7','globe':'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c-5 5-5 13 0 18 5-5 5-13 0-18Z'}
  return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+paths[n]+'"/></svg>'
 def mark():return '<svg viewBox="0 0 52 52" aria-hidden="true"><path d="M3 8 16 44 29 8M31 8v36M49 8v36M31 26h18" fill="none" stroke="currentColor" stroke-width="2"/></svg>'
 def header(l,home=False,p='home'):
  T=lambda en,fa:fa if l=='fa' else en
  base='' if home else page('home',l)
  other=page(p,'en' if l=='fa' else 'fa')
  return f'''<header class="site-header"><div class="nav wrap"><a class="brand" href="{page('home',l)}" aria-label="Vellum House">{mark()}<span>VELLUM HOUSE<small>{T('PRIVATE ACADEMIC MANAGEMENT','مدیریت اختصاصی مسیر تحصیلی')}</small></span></a><button id="menu" type="button" aria-expanded="false" aria-controls="navigation" aria-label="{T('Open menu','باز کردن فهرست')}"><span></span><span></span></button><nav id="navigation" aria-label="{T('Main navigation','فهرست اصلی')}"><a href="{base}#services">{T('Our services','خدمات')}</a><a href="{base}#journey">{T('The approach','مسیر همکاری')}</a><a href="{base}#stories">{T('Results & voices','نتایج و تجربه‌ها')}</a><a href="{page('about',l)}">{T('About us','درباره ما')}</a><a class="language" href="{other}" lang="{'en' if l=='fa' else 'fa'}">{T('فارسی','EN')}</a><a class="button small" href="{base}#consultation">{T('Free consultation','مشاوره رایگان')} {icon('arrow')}</a></nav></div></header>'''
 def footer(l):
  T=lambda en,fa:fa if l=='fa' else en
  return f'''<footer class="site-footer"><div class="wrap footer-grid"><div><a class="brand" href="{page('home',l)}">{mark()}<span>VELLUM HOUSE</span></a><p>{T('For those who do not leave a student’s future to chance.','برای کسانی که آینده تحصیلی را به شانس واگذار نمی‌کنند.')}</p></div><div class="footer-links"><a href="{page('services',l)}">{T('Services','خدمات')}</a><a href="{page('pathways',l)}">{T('Learning pathways','مسیرهای آموزشی')}</a><a href="{page('journal',l)}">{T('Our brochure','معرفی ولوم هاوس')}</a><a href="{page('contact',l)}">{T('Contact','تماس با ما')}</a></div><div><span class="footer-label">{T('START A CONVERSATION','راه ارتباطی')}</span><a class="email-link" href="mailto:reyhaneh.vojoudi@gmail.com" dir="ltr">reyhaneh.vojoudi@gmail.com</a><p class="micro">{T('Online consultation · By arrangement','مشاوره آنلاین · با هماهنگی قبلی')}</p></div></div><div class="wrap footer-bottom"><span>© 2026 Vellum House</span><div><a href="{page('privacy',l)}">{T('Privacy','حریم خصوصی')}</a><a href="{page('terms',l)}">{T('Terms','شرایط همکاری')}</a><a href="#main">{T('Back to top','بازگشت به بالا')} ↑</a></div></div></footer>'''
 def shell(l,p,content,home=False):
  title=C[l]['pages'][p]
  T=lambda en,fa:fa if l=='fa' else en
  return f'''<!doctype html><html lang="{l}" dir="{'rtl' if l=='fa' else 'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | Vellum House</title><meta name="description" content="{esc(C[l]['description'])}"><meta name="theme-color" content="#0b1c2c"><link rel="icon" href="assets/favicon.svg"><link rel="alternate" hreflang="fa" href="{page(p,'fa')}"><link rel="alternate" hreflang="en" href="{page(p,'en')}"><link rel="alternate" hreflang="x-default" href="{page(p,'fa')}"><link rel="stylesheet" href="assets/style.css?v=20261022-3"><script defer src="assets/config.js"></script><script defer src="assets/main.js?v=20261022-3"></script></head><body class="{'home' if home else 'inner'}"><a class="skip" href="#main">{T('Skip to content','رفتن به محتوای اصلی')}</a>{header(l,home,p)}<main id="main">{content}</main>{footer(l)}</body></html>'''
 forms={l:re.search(r'<form id="enquiry-form">.*?</form>',(R/page('contact',l)).read_text()).group(0) for l in ['fa','en']}
 for l in ['fa','en']:
  T=lambda en,fa:fa if l=='fa' else en
  CTA=T('Request a free consultation','درخواست مشاوره رایگان')
  chapters=[('vision',T('The idea','نگاه ما')),('services',T('Services','خدمات')),('pathways',T('Your path','مسیر شما')),('journey',T('The approach','همکاری')),('stories',T('Results','تجربه‌ها')),('consultation',T('Consultation','مشاوره'))]
  dots='<aside class="chapter-nav" aria-label="'+T('Page sections','بخش‌های صفحه')+'">'+''.join(f'<a href="#{k}" aria-label="{v}"><span>{v}</span><i></i></a>' for k,v in chapters)+'</aside>'
  artwork=f'''<div class="portal" role="img" aria-label="{T('Planning, learning and progress connected through a single academic pathway.','برنامه‌ریزی، یادگیری و پیشرفت در یک مسیر تحصیلی پیوسته')}"><svg class="portal-lines" viewBox="0 0 600 590" fill="none" aria-hidden="true"><defs><linearGradient id="goldline" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#d9bd85"/><stop offset="1" stop-color="#8d7040"/></linearGradient><radialGradient id="glow"><stop stop-color="#baa174" stop-opacity=".15"/><stop offset="1" stop-color="#baa174" stop-opacity="0"/></radialGradient></defs><circle cx="300" cy="285" r="245" fill="url(#glow)"/><g stroke="url(#goldline)" opacity=".7"><path d="M127 455V226a173 173 0 0 1 346 0v229"/><path d="M162 440V226a138 138 0 0 1 276 0v214" opacity=".6"/><path d="M197 425V226a103 103 0 0 1 206 0v199" opacity=".4"/><ellipse cx="300" cy="455" rx="235" ry="66" opacity=".25"/><path d="M68 455h464M95 480h410M145 505h310" opacity=".35"/></g><path class="route-line" d="M143 480C225 465 188 362 282 359S395 291 333 253 256 195 300 140" stroke="url(#goldline)" stroke-width="2" stroke-dasharray="5 8"/><g fill="#d9bd85"><circle cx="171" cy="420" r="5"/><circle cx="282" cy="359" r="5"/><circle cx="347" cy="273" r="5"/></g><g stroke="#d9bd85" stroke-width="1.5"><path d="m300 107 5 24 24 5-24 5-5 24-5-24-24-5 24-5z"/><path d="M289 136h22M300 125v22"/></g><g stroke="#bea373" opacity=".45"><path d="M64 256h18M73 247v18M508 367h18M517 358v18"/><circle cx="470" cy="130" r="3"/><circle cx="110" cy="360" r="2"/></g></svg><div class="portal-tag tag-one">{icon('target')}<span>{T('A clear direction','هدف روشن')}</span></div><div class="portal-tag tag-two">{icon('book')}<span>{T('The right learning','یادگیری هدفمند')}</span></div><div class="portal-tag tag-three">{icon('chart')}<span>{T('Connected progress','پیشرفت پیوسته')}</span></div><span class="portal-caption">{T('ONE STUDENT. ONE CONNECTED PLAN.','یک فرد، یک مسیر اختصاصی')}</span></div>'''
  out=dots+f'''<section class="scene hero-scene" id="vision" data-tone="dark"><div class="wrap hero-grid"><div class="hero-copy" data-reveal><p class="eyebrow"><span></span>{T('PRIVATE ACADEMIC MANAGEMENT','مدیریت اختصاصی مسیر تحصیلی')}</p><h1>{T('A future this important<br>deserves <em>a plan.</em>','آینده تحصیلی،<br>اتفاقی <em>ساخته نمی‌شود.</em>')}</h1><p class="hero-lead">{T('Planning, teaching and ongoing guidance.<br>One connected path, built around you.','برنامه‌ریزی، آموزش و پیگیری مستمر<br>در یک مسیر هماهنگ و متناسب با شما.')}</p><div class="actions"><a class="button gold" href="#consultation">{CTA}{icon('arrow')}</a><a class="quiet-link" href="#services">{T('Discover our work','آشنایی با خدمات')}<span>↓</span></a></div><p class="hero-note">{T('From school to university and beyond.','از مدرسه تا دانشگاه و تحصیلات تکمیلی')}</p></div><div data-reveal class="hero-art">{artwork}</div></div><div class="hero-foot wrap"><div class="hero-foot-points"><span>{T('An individual plan','برنامه اختصاصی')}</span><span>{T('Coordinated teaching','آموزش هماهنگ')}</span><span>{T('Clear follow-through','پیگیری روشن')}</span></div><a href="#services" class="scroll-cue">{T('SCROLL TO EXPLORE','ادامه مسیر')}<span>↓</span></a></div></section>'''
  services=[('target',T('A clear plan','برنامه‌ای روشن'),T('Goals, priorities and a roadmap that fits the student.','هدف‌ها، اولویت‌ها و نقشه راه متناسب با شرایط شما.'),T('STRATEGY','برنامه‌ریزی')),('book',T('The right teaching','آموزش متناسب'),T('Specialist online lessons, coordinated around the same plan.','کلاس‌های تخصصی آنلاین، هماهنگ با مسیر کلی تحصیل.'),T('LEARNING','آموزش')),('chart',T('Continuous guidance','همراهی مستمر'),T('Regular reviews, practical adjustments and visible progress.','پیگیری منظم، بازبینی برنامه و گزارش روشن از پیشرفت.'),T('PROGRESS','پیگیری'))]
  cards=''.join(f'<a class="service-node" data-reveal href="{page("services",l)}"><span class="node-number">0{i+1}</span><div class="node-icon">{icon(n)}</div><span class="mini-label">{k}</span><h3>{h}</h3><p>{p}</p><span class="node-arrow">{icon("arrow")}</span></a>' for i,(n,h,p,k) in enumerate(services))
  out+=f'''<section class="scene services-scene" id="services" data-tone="light"><div class="wrap"><div class="section-heading" data-reveal><p class="eyebrow">01 / {T('OUR WORK','خدمات ما')}</p><h2>{T('Every part of education.<br><em>Working together.</em>','همه بخش‌های تحصیل،<br><em>در یک مسیر.</em>')}</h2><p>{T('We connect the decisions, the lessons and the follow-through.','تصمیم‌ها، کلاس‌ها و پیگیری‌ها را به هم وصل می‌کنیم.')}</p></div><div class="service-flow">{cards}</div><a class="under-link" href="{page('services',l)}">{T('Explore all services','همه خدمات ولوم هاوس')}{icon('arrow')}</a></div></section>'''
  stages=[(T('School','مدرسه'),T('Strong foundations. Thoughtful choices.','پایه‌های محکم، انتخاب‌های سنجیده.'),T('A plan for learning, examinations and the next school stage.','برنامه‌ای برای یادگیری بهتر، آمادگی آزمون و انتخاب مسیر آموزشی.'),[T('Subject support','آموزش دروس'),T('Study planning','برنامه‌ریزی مطالعه'),T('Curriculum choices','انتخاب مسیر آموزشی')],'book'),(T('University entry','ورود به دانشگاه'),T('An application with a direction.','پذیرش، در ادامه یک مسیر روشن.'),T('Connect academic preparation, university choices and deadlines.','آمادگی علمی، انتخاب دانشگاه و مهلت‌های درخواست را هماهنگ می‌کنیم.'),[T('University selection','انتخاب دانشگاه'),T('Applications','آمادگی درخواست'),T('Interview preparation','آمادگی مصاحبه')],'cap'),(T('University & beyond','دانشگاه و پس از آن'),T('A purposeful next chapter.','قدم بعدی، با هدفی روشن.'),T('Mentoring for degree studies, postgraduate goals and new skills.','منتورینگ تحصیلی، آمادگی تحصیلات تکمیلی و یادگیری مهارت‌های تازه.'),[T('Academic mentoring','منتورینگ تحصیلی'),T('Graduate applications','تحصیلات تکمیلی'),T('Languages & skills','زبان و مهارت')],'globe')]
  buttons=''.join(f'<button class="stage-tab" id="stage-tab-{i}" role="tab" aria-controls="stage-panel-{i}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-stage="{i}"><span>0{i+1}</span>{s[0]}{icon("arrow")}</button>' for i,s in enumerate(stages))
  panels=''.join(f'<article class="stage-panel" id="stage-panel-{i}" role="tabpanel" aria-labelledby="stage-tab-{i}" tabindex="0"><div class="stage-illustration">{icon(s[4])}<span class="stage-ring"></span></div><div><span class="mini-label">{s[0]}</span><h3>{s[1]}</h3><p>{s[2]}</p><div class="tags">'+''.join(f'<span>{x}</span>' for x in s[3])+f'</div><a class="under-link" href="{page("pathways",l)}#path-{i}">{T("Explore this path","جزئیات این مسیر")}{icon("arrow")}</a></div></article>' for i,s in enumerate(stages))
  out+=f'''<section class="scene pathways-scene" id="pathways" data-tone="light"><div class="wrap pathway-grid"><div data-reveal><p class="eyebrow">02 / {T('YOUR STARTING POINT','نقطه شروع شما')}</p><h2>{T('Where are you<br><em>heading next?</em>','شما در کجای<br><em>مسیر هستید؟</em>')}</h2><div class="stage-tabs" role="tablist" aria-label="{T('Study stage','مرحله تحصیلی')}" aria-orientation="vertical">{buttons}</div></div><div class="stage-panels" data-reveal>{panels}</div></div></section>'''
  steps=[(T('Tell us about yourself','از خودتان بگویید'),T('A short form. Your situation, your goals.','یک فرم کوتاه؛ شرایط فعلی و هدف‌های شما.')),(T('Let’s meet','گفت‌وگو کنیم'),T('A free online consultation, arranged by email.','مشاوره اولیه آنلاین و رایگان، با هماهنگی ایمیلی.')),(T('Choose your next step','آگاهانه شروع کنید'),T('A clear proposal, with scope, timing and fees.','پیشنهادی روشن با خدمات، زمان‌بندی و هزینه مشخص.'))]
  step_html=''.join(f'<article class="journey-step" data-reveal><div class="step-point"><span>0{i+1}</span></div><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate(steps))
  out+=f'''<section class="scene journey-scene" id="journey" data-tone="dark"><div class="wrap"><div class="section-heading" data-reveal><p class="eyebrow">03 / {T('HOW WE BEGIN','مسیر همکاری')}</p><h2>{T('A simple beginning.<br><em>A considered way forward.</em>','شروعی ساده.<br><em>ادامه‌ای سنجیده.</em>')}</h2></div><div class="journey-track">{step_html}</div><div class="journey-bottom"><p>{T('Your first conversation is free. Further support is agreed before it begins.','جلسه آشنایی رایگان است. خدمات بعدی، پیش از شروع با شما توافق می‌شود.')}</p><a class="button gold" href="#consultation">{CTA}{icon('arrow')}</a></div></div></section>'''
  out+=f'''<section class="scene stories-scene" id="stories" data-tone="light"><div class="wrap"><div class="section-heading split-heading" data-reveal><div><p class="eyebrow">04 / {T('RESULTS & VOICES','نتایج و تجربه‌ها')}</p><h2>{T('The journey,<br><em>in their words.</em>','مسیرها و تجربه‌ها،<br><em>از زبان همراهان ما.</em>')}</h2></div><p>{T('Documented outcomes and shared experiences belong here.','اینجا، جای روایت مسیرهای طی‌شده و تجربه همراهی است.')}</p></div><div class="story-grid"><article class="result-space" data-reveal><div class="result-symbol">{icon('cap')}</div><span class="status-pill">{T('COMING SOON','به‌زودی')}</span><h3>{T('Milestones worth sharing','نتیجه‌هایی برای روایت')}</h3><p>{T('Verified academic progress and admission stories will appear here.','نمونه‌های مستند پیشرفت تحصیلی و پذیرش، در این بخش قرار می‌گیرند.')}</p></article><article class="voice-space" data-reveal><span class="quote-mark" aria-hidden="true">“</span><span class="status-pill">{T('COMING SOON','به‌زودی')}</span><h3>{T('The experience of working together','تجربه همراهی با ولوم هاوس')}</h3><p>{T('Student and family feedback, shared with their permission.','بازخورد دانش‌آموزان، دانشجویان و خانواده‌ها، با اجازه خودشان منتشر خواهد شد.')}</p></article></div><div class="founder-strip" data-reveal><span class="founder-mark">{mark()}</span><div><span class="mini-label">{T('ACADEMIC DIRECTION','راهبری علمی')}</span><h3>{T('Reyhaneh Vojoudi','ریحانه وجودی')}</h3><p>{T('Physics educator & researcher · MSc in Gravity and Cosmology','مدرس و پژوهشگر فیزیک · کارشناسی ارشد گرانش و کیهان‌شناسی')}</p></div><a class="under-link" href="{page('about',l)}">{T('Meet the founder','آشنایی با بنیان‌گذار')}{icon('arrow')}</a></div></div></section>'''
  form=forms[l].replace('<h2>', '<h3>').replace('</h2>','</h3>').replace('rows="5"','rows="3"')
  out+=f'''<section class="scene consultation-scene" id="consultation" data-tone="light"><div class="wrap consultation-grid"><div class="consultation-copy" data-reveal><p class="eyebrow">05 / {T('LET’S TALK','شروع گفت‌وگو')}</p><h2>{T('The next step?<br><em>A conversation.</em>','قدم بعدی؟<br><em>یک گفت‌وگو.</em>')}</h2><p>{T('Tell us a little about your situation. We’ll email you to arrange a free initial consultation.','کمی از شرایطتان بنویسید. برای هماهنگی مشاوره اولیه رایگان، به شما ایمیل می‌زنیم.')}</p><div class="consultation-note">{icon('message')}<span>{T('Please check your inbox and spam folder after submitting.','پس از ارسال، صندوق ورودی و پوشه اسپم ایمیلتان را بررسی کنید.')}</span></div><a class="quiet-link" href="{page('contact',l)}">{T('Questions before we meet?','پیش از جلسه، پرسشی دارید؟')}{icon('arrow')}</a></div><div class="form-panel" data-reveal>{form}</div></div></section>'''
  doc=shell(l,'home',out,True)
  (R/page('home',l)).write_text(doc)
  if l=='fa':(R/'fa.html').write_text(doc)
  # Keep the existing service/legal/form content; give every page the same visual shell.
  for p in C[l]['pages']:
   if p=='home':continue
   old=(R/page(p,l)).read_text()
   main=old.split('<main id="main">',1)[1].split('<footer',1)[0]
   main=main.split('<section class="closing">',1)[0].removesuffix('</main>')
   if p not in ['contact','privacy','terms']:
    main+=f'<section class="compact-cta wrap"><h2>{T("Let’s find your next step.","قدم بعدی را با هم پیدا کنیم.")}</h2><a class="button" href="{page("home",l)}#consultation">{CTA}{icon("arrow")}</a></section>'
   (R/page(p,l)).write_text(shell(l,p,main))
 (R/'404.html').write_text('<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>صفحه پیدا نشد | Vellum House</title><link rel="stylesheet" href="assets/style.css"><body class="inner"><main class="page-hero wrap"><p class="eyebrow">404</p><h1>این صفحه پیدا نشد</h1><a class="button" href="index.html">بازگشت به خانه</a> <a href="en.html">English home</a></main></body></html>')
